stylesheet:
/* ambient occlusion · soft grey ground, white bound panels, Onest, one cobalt signal.
   The top bar scrolls away and a floating dock takes over; a hairline at the top of thread pages
   shows reading progress. Both use CSS scroll-driven animations, so there is no script and
   browsers without support simply keep a sticky top bar. */
@font-face { font-family: Onest; font-style: normal; font-weight: 100 900; font-display: swap; src: url('/static/fonts/Onest-latin.woff2') format('woff2'); }
@font-face { font-family: Onest; font-style: normal; font-weight: 100 900; font-display: swap; src: url('/static/fonts/Onest-latin-ext.woff2') format('woff2'); unicode-range: U+0100-024F, U+0259, U+1E00-1EFF, U+2020, U+20A0-20AB, U+20AD-20CF, U+2113, U+2C60-2C7F, U+A720-A7FF; }
@font-face { font-family: Onest; font-style: normal; font-weight: 100 900; font-display: swap; src: url('/static/fonts/Onest-cyrillic.woff2') format('woff2'); unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116; }

/* ================================================================== tokens */
:root:root:root {
  --brand: #1f45e0;
  --canvas: #f5f5f7; --surface: #ffffff; --surface-2: #fcfcfd; --surface-3: #f2f2f5;
  --ink: #1d1d1f; --ink-soft: #5e5e63; --ink-faint: #6e6e73;
  --rule: #e3e3e8; --rule-strong: #d2d2d7; --glass: rgba(255, 255, 255, .86);
  --signal: #1f45e0; --signal-strong: #1736b8; --signal-ink: #fff;
  --signal-wash: #e8ecfc; --signal-soft: #d6defa; --link: #1f45e0; --ring: rgba(31, 69, 224, .28);
  --live: #1e9e74;
  --line-0: #1f45e0; --line-1: #c98a1b; --line-2: #8a55d6; --line-3: #1e9e74; --line-4: #d2476e; --line-5: #6e6e73;
  --quote-bg: #f5f5f7; --code-bg: #f5f5f7;
  --radius-sm: 8px; --radius: 10px; --radius-lg: 14px; --radius-xl: 20px;
  --shadow-sm: none; --shadow: 0 1px 2px rgba(0, 0, 0, .04), 0 10px 30px -18px rgba(0, 0, 0, .18); --shadow-lg: 0 10px 30px rgba(0, 0, 0, .14);
  --font-ui: Onest, -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  --font-display: var(--font-ui); --font-read: var(--font-ui);
  --page: 1088px; --header-h: 60px;
  --ao-bubble-in: #f0f0f3; --ao-dock: rgba(29, 29, 31, .92); --ao-dock-ink: #f5f5f7; --ao-dock-soft: #a1a1a8;
}
@media (prefers-color-scheme: dark) {
  :root:root:root:not([data-colormode="light"]) {
    --canvas: #000; --surface: #1c1c1e; --surface-2: #202023; --surface-3: #2c2c2e;
    --ink: #f5f5f7; --ink-soft: #a1a1a6; --ink-faint: #98989d;
    --rule: #2c2c2e; --rule-strong: #3a3a3c; --glass: rgba(28, 28, 30, .86);
    --signal-strong: #9db0ff; --signal-wash: rgba(31, 69, 224, .24); --signal-soft: rgba(31, 69, 224, .36); --link: #8ea2ff; --ring: rgba(120, 145, 255, .35);
    --quote-bg: #2c2c2e; --code-bg: #141416; --ao-bubble-in: #2c2c2e; --ao-dock: rgba(58, 58, 60, .92);
    --line-5: #98989d;
  }
}
:root:root:root[data-colormode="dark"] {
  --canvas: #000; --surface: #1c1c1e; --surface-2: #202023; --surface-3: #2c2c2e;
  --ink: #f5f5f7; --ink-soft: #a1a1a6; --ink-faint: #98989d;
  --rule: #2c2c2e; --rule-strong: #3a3a3c; --glass: rgba(28, 28, 30, .86);
  --signal-strong: #9db0ff; --signal-wash: rgba(31, 69, 224, .24); --signal-soft: rgba(31, 69, 224, .36); --link: #8ea2ff; --ring: rgba(120, 145, 255, .35);
  --quote-bg: #2c2c2e; --code-bg: #141416; --ao-bubble-in: #2c2c2e; --ao-dock: rgba(58, 58, 60, .92);
  --line-5: #98989d;
}

body { font-size: 15px; letter-spacing: 0; }
h1, h2, h3, h4 { letter-spacing: -.02em; }
::selection { background: rgba(31, 69, 224, .2); }
.wrap { padding: 0 24px; }

/* ================================================================== top bar */
.site-header { background: var(--surface); backdrop-filter: none; -webkit-backdrop-filter: none; border-bottom: 1px solid var(--rule); }
.site-header .wrap { max-width: none; padding: 0 32px; }
.site-header .bar { gap: 32px; }
.ao-mark { display: inline-block; width: 20px; height: 20px; border-radius: 6px; background: var(--signal); flex: none; }
.logo { gap: 9px; font: 700 16px/1 var(--font-ui); letter-spacing: -.01em; }
.tabs { gap: 4px; }
.tabs a { height: 32px; padding: 0 12px; border-radius: 8px; color: var(--ink); font-size: 14px; font-weight: 500; }
.tabs a:hover { background: var(--canvas); }
.tabs a[aria-current="page"] { background: var(--canvas); font-weight: 500; }
.quicksearch svg { left: 12px; width: 14px; height: 14px; color: var(--ink-soft); }
.quicksearch input[type=search] { width: 240px; height: 34px; border-radius: 9px; background: var(--canvas); font-size: 14px; padding-left: 33px; }
.quicksearch input[type=search]::placeholder { color: var(--ink-soft); }
.quicksearch input[type=search]:focus { width: 280px; }
.icon-btn { width: 36px; height: 36px; color: var(--ink); }
.icon-btn svg { width: 19px; height: 19px; }
.icon-btn:hover { background: var(--canvas); }
.usermenu summary { padding: 3px; }
.usermenu summary .uname { display: none; }
.usermenu summary:hover, .usermenu[open] summary { background: var(--canvas); }
.usermenu .menu { border-radius: 14px; border-color: var(--rule); }

/* ================================================================== dock + reading progress */
.ao-dock, .ao-progress { display: none; }
@supports (animation-timeline: scroll()) {
  .site-header { position: relative; }
  .ao-dock {
    position: fixed; left: 50%; bottom: 28px; z-index: 50; display: flex; align-items: center; gap: 4px;
    max-width: calc(100vw - 32px); height: 60px; padding: 0 10px 0 18px; border-radius: 999px;
    background: var(--ao-dock); color: var(--ao-dock-ink); font-size: 14px; font-weight: 500;
    backdrop-filter: blur(20px) saturate(1.6); -webkit-backdrop-filter: blur(20px) saturate(1.6);
    box-shadow: 0 10px 30px rgba(0, 0, 0, .18), inset 0 1px 0 rgba(255, 255, 255, .08);
    opacity: 0; visibility: hidden; transform: translate(-50%, 24px) scale(.96);
    animation: ao-dock-in linear both, ao-dock-out linear both; animation-timeline: scroll(root), scroll(root);
    animation-range: 60px 160px, calc(100% - 160px) calc(100% - 40px);
  }
  @keyframes ao-dock-in { to { opacity: 1; visibility: visible; transform: translate(-50%, 0) scale(1); } }
  /* …and steps aside at the end of the page so it never covers the footer. */
  @keyframes ao-dock-out { to { opacity: 0; visibility: hidden; transform: translate(-50%, 24px) scale(.96); } }
  .ao-progress {
    display: block; position: fixed; inset: 0 0 auto; height: 3px; z-index: 60; background: var(--signal);
    border-radius: 0 999px 999px 0; transform-origin: 0 50%; transform: scaleX(0);
    animation: ao-progress linear both; animation-timeline: scroll(root);
  }
  @keyframes ao-progress { to { transform: scaleX(1); } }
}
.ao-dock a { color: inherit; display: flex; align-items: center; gap: 7px; height: 40px; padding: 0 12px; border-radius: 999px; white-space: nowrap; }
.ao-dock a:hover { background: rgba(255, 255, 255, .1); text-decoration: none; }
.ao-dock .ao-mark { width: 18px; height: 18px; }
.ao-dock .ao-home { padding: 0 8px 0 0; height: 40px; }
.ao-dock .ao-home:hover { background: none; }
.ao-dock .ao-sep { width: 1px; height: 22px; background: rgba(255, 255, 255, .14); flex: none; margin: 0 6px; }
.ao-dock .ao-icon { width: 40px; padding: 0; justify-content: center; position: relative; }
.ao-dock svg { width: 17px; height: 17px; }
.ao-dock .badge { box-shadow: none; }
.ao-dock .ao-icon .badge { position: absolute; top: 3px; right: 0; }
.ao-dock .ao-title { flex: 1 1 auto; min-width: 0; max-width: 300px; padding: 0 12px; color: var(--ao-dock-soft); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ao-dock .ao-cta { background: var(--signal); color: #fff; font-weight: 600; padding: 0 18px; margin-left: 4px; }
.ao-dock .ao-cta:hover { background: var(--signal-strong); }
:root[data-colormode="dark"] .ao-dock .ao-cta:hover { background: #2c55f0; }

/* ================================================================== page furniture */
main.wrap { padding-top: 36px; }
.navline { margin: 0 0 12px; font-size: 14px; font-weight: 500; color: var(--ink-soft); gap: 0; }
.navline a { color: var(--ink-soft); padding: 2px 4px; border-radius: 6px; }
.navline a:last-of-type { color: var(--ink); }
.navline a:hover { background: var(--surface-3); }
.navline .sep::before { color: #9a9aa0; }
.navline .sep:has(+ .current), .navline .current { display: none; }
.page-head h1, .thread-head h1 { font-size: 34px; line-height: 40px; font-weight: 700; letter-spacing: -.022em; }
.box, .forum-list, .thread-list, .post, .sidenav, .metric, .profile-card { box-shadow: none; border-color: var(--rule); }
.box { border-radius: var(--radius-lg); }
.box-head h2, .box-head h3 { font-size: 15px; font-weight: 700; }
table.grid th { background: transparent; font-size: 12px; font-weight: 600; color: var(--ink-soft); letter-spacing: 0; }
.notice { box-shadow: none; }

/* buttons: pills, cobalt or white-with-hairline */
.btn, button.btn, input[type=submit].btn { height: 34px; padding: 0 18px; font-size: 14px; font-weight: 600; box-shadow: none; }
.btn.secondary { background: var(--surface); color: var(--ink); border-color: var(--rule); }
.btn.secondary:hover { background: var(--canvas); border-color: var(--rule-strong); }
.btn.ghost:hover { background: var(--surface-3); }
.btn.small { height: 30px; padding: 0 14px; font-size: 13px; }
input[type=text], input[type=password], input[type=email], input[type=number], input[type=url], input[type=search],
input[type=date], input[type=datetime-local], input[type=time], select, textarea { background: var(--surface); border-color: var(--rule-strong); border-radius: 9px; }
.pagination .current { background: var(--signal); color: #fff; }
.editor { border-radius: 12px; border-color: var(--rule-strong); }
.editor-toolbar { background: var(--surface); }

/* ================================================================== board index */
.ao-board-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px 24px; flex-wrap: wrap; margin: 4px 0 28px; }
.ao-board-head .grow { flex: 1 1 520px; min-width: 0; }
.ao-eyebrow { display: block; font-size: 14px; font-weight: 500; color: var(--ink-soft); margin-bottom: 6px; }
.ao-board-head h1 { margin: 0; font-size: 34px; line-height: 40px; font-weight: 700; letter-spacing: -.022em; }
.ao-board-head .lede { margin: 8px 0 0; color: var(--ink-soft); max-width: 62ch; }
.ao-board-head .actions { margin: 0; }
.ao-board-head form { display: inline; }

.cat { margin: 0 0 20px; background: var(--surface); border: 1px solid var(--rule); border-radius: var(--radius-lg); overflow: hidden; }
.cat .forum-list { border: 0; border-radius: 0; background: transparent; }
.cat-head, .forum-row { display: grid; grid-template-columns: 40px minmax(0, 1fr) 72px 72px 260px; gap: 16px; align-items: center; padding: 18px 24px; }
.cat-head { padding: 0 24px; min-height: 48px; border-bottom: 1px solid var(--rule); font-size: 12px; font-weight: 600; color: var(--ink-soft); }
.cat.collapsed .cat-head { border-bottom: 0; }
.cat-head .ao-cat-title { grid-column: 1 / 3; display: flex; align-items: baseline; gap: 10px; min-width: 0; }
.cat-head h2 { margin: 0; font-size: 15px; font-weight: 700; letter-spacing: -.01em; white-space: nowrap; }
.cat-head h2::before { content: none; }
.cat-head .desc { padding: 0; margin: 0; flex-basis: auto; font-size: 13px; font-weight: 500; color: var(--ink-soft); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cat-head .desc p { margin: 0; display: inline; }
.cat-head .ao-col { text-align: right; }
.cat-head .ao-col-last { padding-left: 38px; display: flex; align-items: center; justify-content: space-between; }
.cat-head .collapse-toggle { order: 0; margin: 0 -6px 0 0; width: 28px; height: 28px; }
.forum-row + .forum-row { border-top: 1px solid var(--rule); }
.forum-row:hover { background: var(--surface-2); }
.forum-row .forum-stats { display: contents; }
.forum-row .forum-stats > div { font-size: 0; text-align: right; }
.forum-row .forum-stats b { display: inline; font-size: 14px; font-weight: 500; color: var(--ink); }
.forum-row .lastpost { grid-column: 5; padding-left: 12px; }
.forum-icon, .forum-row.unread .forum-icon { width: 40px; height: 40px; border-radius: 11px; background: var(--canvas); box-shadow: none; }
.forum-icon svg { display: none; }
.forum-icon::before { content: ""; width: 12px; height: 12px; border-radius: 50%; background: var(--line); }
.forum-row.unread .forum-icon { background: color-mix(in oklab, var(--line) 12%, var(--surface)); }
.forum-row.unread .forum-icon::after { content: none; }
.forum-row:hover .forum-icon { transform: none; }
.forum-icon.is-locked::before, .forum-icon.is-link::before { background: var(--ink-faint); }
.forum-name { font-size: 16px; font-weight: 600; letter-spacing: -.005em; }
.forum-row.unread .forum-name { font-weight: 700; }
.forum-row.unread .forum-name::after { content: "New"; display: inline-flex; align-items: center; height: 18px; padding: 0 7px; margin-left: 8px; border-radius: 999px; background: var(--signal); color: #fff; font-size: 11px; font-weight: 700; vertical-align: 2px; }
.forum-desc { font-size: 14px; line-height: 20px; margin-top: 3px; }
.lastpost { gap: 10px; font-size: 13px; }
.lastpost .face { --size: 28px; }
.lastpost .lp-text { line-height: 20px; }
.lastpost .subject, .lastpost a.subject { font-size: 14px; font-weight: 600; color: var(--ink); }
.lastpost .by a { font-weight: 500; }
.subforums a { background: var(--canvas); }

/* ================================================================== thread lists (forum view, search) */
.thread-row:hover, .forum-row:hover { background: var(--surface-2); }
.thread-title { font-size: 15px; font-weight: 600; }
.thread-row.unread .thread-title a { font-weight: 700; }
.thread-row.unread .face { box-shadow: 0 0 0 2px var(--surface), 0 0 0 4px var(--signal); }
.thread-row.sticky { background: var(--surface-2); }
.newlink { background: var(--signal); color: #fff; }
.flag.sticky { background: var(--signal-wash); color: var(--signal); }

/* ================================================================== thread page */
.thread-head { margin: 0 0 28px; align-items: center; }
.thread-head .meta { gap: 6px 8px; margin-top: 12px; font-size: 14px; }
.thread-head .meta .chip { display: none; }
.thread-head .meta > span + span::before { content: "· "; color: #a1a1a8; }
.thread-head .meta a { color: var(--ink); font-weight: 600; }
.postlist { gap: 14px; }
.post { grid-template-columns: 208px minmax(0, 1fr); border-radius: var(--radius-lg); }
.post-author { padding: 28px 20px; background: var(--surface-2); border-right-color: var(--rule); border-radius: var(--radius-lg) 0 0 var(--radius-lg); }
.post-author-inner { gap: 4px; }
.post-author .face, .post-author .face:has(.presence) img { --size: 72px; border-radius: 999px; margin-bottom: 10px; box-shadow: none; }
.post-author .name { font-size: 16px; }
.post-author .role { font-size: 12px; font-weight: 600; background: var(--canvas); padding: 2px 8px; }
.author-stats { margin-top: 14px; padding-top: 14px; gap: 6px; font-size: 13px; }
.author-stats dt { color: var(--ink-soft); }
.author-stats dd { font-weight: 500; }
.post-head { padding: 22px 32px 0; font-size: 13px; color: var(--ink-soft); }
.post-head .when { flex: 1 1 auto; margin-left: 0; gap: 10px; }
.post-head .when a { color: var(--ink-soft); }
.post-head .when .num { margin-left: auto; font-weight: 600; }
.post-body { padding: 16px 32px 20px; font-size: 17px; line-height: 28px; letter-spacing: 0; }
.post-body > * { max-width: 700px; }
.post-body p { margin: 0 0 18px; }
.post-body img:not(.smilie) { border-radius: 10px; }
.post-edited { padding: 0 32px 12px; }
.post-attachments { margin: 0 32px 18px; background: var(--canvas); }
.signature { margin: 0 32px 4px; padding: 16px 0 12px; font-size: 13px; color: var(--ink-soft); }
.post-foot { padding: 10px 24px 14px 28px; border-top: 0; gap: 4px; }
.post-foot .btn, .post-foot .btn.secondary, .post-foot .btn:not(.secondary) { height: 30px; padding: 0 9px; background: transparent; color: var(--ink-soft); font-size: 13px; font-weight: 600; border: 0; }
.post-foot .btn:hover, .post-foot .btn:not(.secondary):hover { background: var(--canvas); color: var(--ink); }
.post-foot .btn[aria-pressed="true"] { background: var(--signal-wash); color: var(--signal); }
.reactions { padding-left: 0; }
.reaction { height: 30px; border: 0; background: var(--canvas); font-size: 13px; font-weight: 600; padding: 0 12px; }
.reaction.mine { background: var(--signal-wash); color: var(--signal); }
.post:target, .post.is-new { border-color: color-mix(in oklab, var(--signal) 45%, transparent); box-shadow: 0 0 0 3px var(--ring); }
.mycode_quote { margin: 0 0 18px; padding: 14px 18px; background: var(--quote-bg); border-left: 0; border-radius: 10px; font-size: 15px; line-height: 24px; color: color-mix(in oklab, var(--ink) 85%, var(--canvas)); }
.mycode_quote cite { font-size: 13px; font-weight: 600; color: var(--ink-soft); margin-bottom: 6px; }
.mycode_quote .mycode_quote { background: var(--surface); }
.codeblock { border-radius: 10px; }
.mycode_mention { background: var(--signal-wash); color: var(--signal); }
.composer { padding: 20px 24px; }
.quickreply { border-radius: var(--radius-lg); }

/* ================================================================== private messages */
.ao-folders { display: inline-flex; flex-wrap: wrap; gap: 2px; padding: 3px; border-radius: 999px; background: var(--surface-3); font-size: 13px; }
.ao-folders a { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 12px; border-radius: 999px; color: var(--ink-soft); font-weight: 600; }
.ao-folders a:hover { color: var(--ink); text-decoration: none; }
.ao-folders a.active { background: var(--surface); color: var(--ink); box-shadow: 0 1px 2px rgba(0, 0, 0, .06); }
.ao-panel { background: var(--surface); border: 1px solid var(--rule); border-radius: var(--radius-lg); overflow: hidden; }
.ao-convos { list-style: none; margin: 0; padding: 0; }
.ao-convo { position: relative; display: grid; grid-template-columns: 10px 40px minmax(0, 1fr) auto 20px; gap: 12px; align-items: center; padding: 14px 16px; border-bottom: 1px solid var(--rule); }
.ao-convo:last-child { border-bottom: 0; }
.ao-convo:hover { background: var(--surface-2); }
.ao-convo .ao-unread-dot { width: 8px; height: 8px; border-radius: 50%; background: transparent; }
.ao-convo.unread .ao-unread-dot { background: var(--signal); }
.ao-convo .face { --size: 40px; }
.ao-convo .ao-who { display: block; font-size: 15px; font-weight: 600; color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ao-convo .ao-who a { color: inherit; position: relative; z-index: 1; }
.ao-convo .ao-subject { display: block; font-size: 14px; color: var(--ink-soft); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ao-convo .ao-subject a { color: inherit; }
.ao-convo .ao-subject a::after { content: ""; position: absolute; inset: 0; }
.ao-convo.unread .ao-who { font-weight: 700; }
.ao-convo.unread .ao-subject { color: var(--ink); }
.ao-convo .ao-when { align-self: start; padding-top: 2px; font-size: 13px; color: var(--ink-soft); white-space: nowrap; font-variant-numeric: tabular-nums; }
.ao-convo input[type=checkbox] { position: relative; z-index: 1; }
.ao-convo .ao-state { font-size: 12px; color: var(--ink-faint); }
.ao-convos .empty { padding: 40px 20px; text-align: center; color: var(--ink-soft); }

.ao-convo-view { display: flex; flex-direction: column; }
.ao-convo-head { display: flex; align-items: center; gap: 12px; padding: 16px 20px; border-bottom: 1px solid var(--rule); }
.ao-convo-head .face { --size: 40px; }
.ao-convo-head .ao-who { display: flex; flex-direction: column; min-width: 0; flex: 1 1 auto; }
.ao-convo-head .ao-who b { font-size: 15px; font-weight: 700; }
.ao-convo-head .ao-who b a { color: var(--ink); }
.ao-convo-head .ao-who span { font-size: 13px; color: var(--ink-soft); }
.ao-convo-head .ao-who span a { color: var(--ink-soft); }
.ao-back { display: inline-flex; align-items: center; gap: 4px; font-size: 14px; font-weight: 500; color: var(--signal); }
.ao-thread { display: flex; flex-direction: column; gap: 6px; padding: 24px 24px 22px; }
.ao-subject-line { align-self: flex-start; font-size: 13px; font-weight: 600; color: var(--ink-soft); margin: 0 0 2px 14px; }
.ao-thread.out .ao-subject-line { align-self: flex-end; margin: 0 14px 2px 0; }
.ao-bubble { align-self: flex-start; max-width: min(620px, 82%); padding: 12px 16px; border-radius: 20px 20px 20px 6px; background: var(--ao-bubble-in); color: var(--ink); font-size: 15px; line-height: 23px; overflow-wrap: anywhere; }
.ao-bubble.post-body { padding: 12px 16px; flex: none; font-size: 15px; line-height: 23px; }
.ao-bubble > * { max-width: none; }
.ao-bubble p { margin: 0 0 10px; }
.ao-bubble .mycode_quote { background: rgba(0, 0, 0, .05); margin-bottom: 10px; }
.ao-thread.out .ao-bubble { align-self: flex-end; border-radius: 20px 20px 6px 20px; background: var(--signal); color: #fff; }
.ao-thread.out .ao-bubble a { color: #fff; }
.ao-thread.out .ao-bubble .mycode_quote { background: rgba(255, 255, 255, .16); color: #fff; }
.ao-thread.out .ao-bubble .mycode_quote cite { color: rgba(255, 255, 255, .8); }
