.ao-mail-search svg { position: absolute; left: 11px; width: 14px; height: 14px; color: var(--ink-soft); pointer-events: none; }
.ao-mail-search input[type=search] { width: 220px; height: 34px; padding: 0 12px 0 32px; border: 0; border-radius: 9px; background: var(--canvas); font-size: 14px; }
