.ao-community { margin-top: 28px; }
.ao-community .forum-row.unread .forum-name::after { content: none; }
.ao-community .forum-name { font-weight: 600; }
.ao-community .cat-head h2 { color: var(--ink); }
.ao-live-icon::before { background: var(--ink-faint); }
.ao-online.unread .ao-live-icon { background: color-mix(in oklab, var(--live) 14%, var(--surface)); }
.ao-online.unread .ao-live-icon::before { background: var(--live); box-shadow: 0 0 0 4px color-mix(in oklab, var(--live) 22%, transparent); animation: ao-pulse 2.4s ease-in-out infinite; }
@keyframes ao-pulse { 50% { box-shadow: 0 0 0 7px color-mix(in oklab, var(--live) 0%, transparent); } }
.ao-totals-icon::before { border-radius: 3px; background: var(--signal); }
.ao-community .ao-people { display: flex; align-items: center; gap: 10px; margin-top: 4px; font-size: 14px; color: var(--ink-soft); min-width: 0; }
.ao-community .ao-people > span:last-child { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ao-community .ao-people a { color: var(--ink); font-weight: 500; }
.ao-faces { display: inline-flex; flex: none; }
.ao-faces .face { --size: 26px; box-shadow: 0 0 0 2px var(--surface); }
