@media (max-width: 980px) { .ao-community .forum-row > .ao-num, .ao-community .forum-row > span:empty { display: none; } }

/* ================================================================== admin debug bar */
.devbar { font: 12px/1.45 var(--font-code); background: var(--surface); color: var(--ink-soft); border-top: 1px solid var(--rule); }
.devbar summary { gap: 8px; padding: 10px 32px; max-width: none; }
.devbar summary::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--ink-faint); margin-right: 2px; }
