templates.pm/folder.html:
{% extends "pm/base.html" %}
{% import "macros.html" as m %}
{% block pmsearch %}
<form method="get" action="/pm" class="ao-mail-search" role="search"><input type="hidden" name="folder" value="{{ folder }}">
  <svg viewBox="0 0 20 20" aria-hidden="true"><path d="M8.5 3a5.5 5.5 0 0 1 4.38 8.83l3.65 3.64-1.06 1.06-3.64-3.65A5.5 5.5 0 1 1 8.5 3zm0 1.5a4 4 0 1 0 0 8 4 4 0 0 0 0-8z" fill="currentColor"/></svg>
  <input type="search" name="q" value="{{ search }}" placeholder="Search {{ folder_name|lower }}" aria-label="Search messages">
</form>
{% endblock %}
{% block pm %}
<form method="post" action="/pm/action" id="pmlist" class="ao-mail-list">{{ m.csrf_field() }}<input type="hidden" name="folder" value="{{ folder }}">
  <ul class="ao-convos">
  {% for p in messages %}
    {% set unread = p.status == 0 and folder not in [2, 3] %}
    <li class="ao-convo{% if unread %} unread{% endif %}">
      <span class="ao-unread-dot" aria-hidden="true"></span>
      <span class="face av-{{ p.other_uid % 6 }}" style="--size:40px" aria-hidden="true"><svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor"><circle cx="12" cy="8.5" r="4"/><path d="M4.5 20a7.5 7.5 0 0 1 15 0z"/></svg></span>
      <div>
        <span class="ao-who">{% if folder in [2, 3] %}<span class="faint">To </span>{% endif %}{% if p.other_uid %}<a href="{{ url_user(p.other_uid) }}">{{ p.other|safe }}</a>{% else %}{{ p.other|safe }}{% endif %}{% if p.pgp == 2 %}<span class="pgp-flag is-encrypted" title="End-to-end encrypted"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V8a4 4 0 118 0v3"/></svg><span class="sr-only">Encrypted</span></span>{% elif p.pgp == 1 %}<span class="pgp-flag is-signed" title="Signed"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3l7 3v5c0 4.6-3 8.4-7 10-4-1.6-7-5.4-7-10V6z"/></svg><span class="sr-only">Signed</span></span>{% endif %}{% if p.multi %} <span class="ao-state">· group</span>{% endif %}</span>
        <span class="ao-subject">{% if unread %}<span class="sr-only">Unread: </span>{% endif %}<a href="/pm/read/{{ p.pmid }}">{{ p.subject }}</a>{% if p.status == 3 %} <span class="ao-state">· replied</span>{% elif p.status == 4 %} <span class="ao-state">· forwarded</span>{% endif %}</span>
      </div>
      <span class="ao-when">{{ p.dateline|date }}</span>
      <input type="checkbox" name="pmids" value="{{ p.pmid }}" aria-label="Select message">
    </li>
  {% else %}
    <li class="empty">{{ "No messages match your search." if search else "There are no messages in this folder." }}</li>
  {% endfor %}
  </ul>
  {% if messages %}
  <div class="ao-bulk">
    <span class="ao-bulk-label">Selected:</span>
    <select name="action" aria-label="Action"><option value="read">Mark as read</option><option value="unread">Mark as unread</option><option value="delete">Delete</option><option value="move">Move to…</option>{% if folder == 4 %}<option value="emptytrash">Empty trash can</option>{% endif %}</select>
    <select name="target" aria-label="Target folder">{% for f in folders %}{% if f[0] != 3 %}<option value="{{ f[0] }}">{{ f[1] }}</option>{% endif %}{% endfor %}</select>
    <button class="btn small" type="submit">Apply</button>
  </div>
  {% endif %}
</form>
{% if quota or pagination.pages > 1 %}
<footer class="ao-mail-foot">
  {% if pagination.pages > 1 %}{{ m.pagination(pagination) }}{% endif %}
  <span class="spacer"></span>
  {% if quota %}<span class="ao-quota">{{ used }} of {{ quota }} messages<span class="meter" style="width:80px"><span style="width:{{ [used * 100 // quota, 100]|min }}%"></span></span></span>{% endif %}
</footer>
{% endif %}
{% endblock %}

templates.pm/read.html:
{% extends "pm/base.html" %}
{% import "macros.html" as m %}
{% block head %}{% if pgp %}<script type="module" src="{{ asset('js/pgp.mjs') }}"></script>{% endif %}{% endblock %}
{% block pm %}
{% if pgp %}<script type="application/json" id="pgp-data">{{ pgp|tojson }}</script>{% endif %}
{% set outgoing = pm.folder == 2 %}
<article class="ao-convo-view"{% if pgp %} data-pgp-read data-pgp-board="{{ board }}"{% endif %}>
  <header class="ao-convo-head">
    <a class="ao-back" href="/pm?folder={{ pm.folder }}" aria-label="Back to the folder"><svg viewBox="0 0 16 16" width="14" height="14" fill="none" aria-hidden="true"><path d="M10 3 5 8l5 5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></a>
    {% if author %}{{ m.face(author.avatar, author.username, author.uid, 40, '', author.online) }}{% else %}{{ m.face('', system_name, 0, 40) }}{% endif %}
    <div class="ao-who">
      {% if author %}<b><a href="{{ url_user(author.uid, author.username) }}">{{ author.formatted|safe }}</a></b>{% else %}<b>{{ system_name }}</b>{% endif %}
      <span>{% if author %}{{ author.usertitle }}{% else %}System message{% endif %}{% if to %}{% if author and author.usertitle %} · {% endif %}to {% for t_ in to %}<a href="{{ url_user(t_[0]) }}">{{ t_[1] }}</a>{% if not loop.last %}, {% endif %}{% endfor %}{% endif %}</span>
    </div>
    {% if pgp %}<div class="pgp-msg-seal" aria-live="polite"><noscript><span class="pgp-seal is-pending"><span class="pgp-seal-text"><strong>{{ 'Encrypted message' if pgp.level == 2 else 'Signed message' }}</strong><small>Enable JavaScript to check the signature{{ ' and read it' if pgp.level == 2 else '' }}.</small></span></span></noscript></div>
    {% elif sender_has_key and pm.folder != 2 %}<div class="pgp-msg-seal"><span class="pgp-seal is-off" title="{{ author.username if author else '' }} has an identity key but didn't sign this message"><span class="pgp-seal-text"><strong>Not signed</strong></span></span></div>{% endif %}
  </header>
  <div class="ao-thread{% if outgoing %} out{% endif %}">
    {% if from_system and pm.folder != 2 %}<p class="notice small system-notice">This is an automated message from the System account, so replies aren't read.{% if can_contact %} If you need help, <a href="/contact">contact the staff</a>.{% endif %}</p>{% endif %}
    <span class="ao-subject-line">{{ pm.subject }}</span>
    <div class="ao-bubble post-body js-pm-body">{{ html|safe }}</div>
    <span class="ao-stamp">{{ pm.dateline|date('datetime') }}</span>
    {% if author and author.signature and pm.includesig and not pgp %}<div class="signature">{{ author.signature|safe }}</div>{% endif %}
  </div>
  <footer class="ao-reply-bar">
    {% if pm.fromid and pm.folder != 2 and not from_system %}
      <a class="ao-reply-pill" href="/pm/send?pmid={{ pm.pmid }}">Reply to {{ author.username if author else 'this message' }}…</a>
      <a class="btn secondary small" href="/pm/send?pmid={{ pm.pmid }}&mode=replyall">Reply all</a>
    {% else %}<span class="spacer"></span>{% endif %}
    <a class="btn secondary small" href="/pm/send?pmid={{ pm.pmid }}&mode=forward">Forward</a>
    <form method="post" action="/pm/action">{{ m.csrf_field() }}<input type="hidden" name="pmids" value="{{ pm.pmid }}"><input type="hidden" name="folder" value="{{ pm.folder }}"><button class="btn secondary small" name="action" value="delete">Delete</button></form>
    {% if pm.fromid and pm.fromid != me.uid and not from_system %}
    <details class="ao-more up">
      <summary aria-label="More"><svg viewBox="0 0 20 20" width="18" height="18" aria-hidden="true"><circle cx="4.5" cy="10" r="1.6" fill="currentColor"/><circle cx="10" cy="10" r="1.6" fill="currentColor"/><circle cx="15.5" cy="10" r="1.6" fill="currentColor"/></svg></summary>
      <div class="menu" role="menu">
        <a href="/pm/verify/{{ pm.fromid }}">Verify identity</a>
        {% if pm.folder != 2 %}<a href="/report?type=pm&id={{ pm.pmid }}">Report</a>{% endif %}
      </div>
    </details>
    {% endif %}
  </footer>
</article>
{% endblock %}
